// @nullarch/resin-lightweight-charts — render resin's Pine visualization data on
// TradingView's lightweight-charts.
//
// Two entry points:
//   applyResinViz(chart, vizOrRunResult, bars, opts?)  — you own the chart
//   renderResinViz(container, vizOrRunResult, bars, opts?) — batteries included
//
// The pure mapping tables live under src/map/ and are the tested core; apply.ts
// is a thin walk over the viz object. The support matrix in the README is the
// authoritative statement of what is faithful, approximated, and not yet drawn.
import { createChart } from "lightweight-charts";
import { applyResinViz } from "./apply";
export { applyResinViz } from "./apply";
/** Create a chart in `container` and apply the viz in one call. */
export function renderResinViz(container, source, bars, options = {}) {
    const chart = createChart(container, options.chart);
    const handle = applyResinViz(chart, source, bars, options);
    return { chart, ...handle };
}
